import { ConfigUrl } from '../../../../configs/url'

export const WITHDRAWAL_ACTIONS = {
  GET_BANK_LIST_REQUEST: 'GET_BANK_LIST_REQUEST',
  GET_BANK_LIST: 'GET_BANK_LIST',

  GET_WITHDRAWAL_LIST_REQUEST: 'GET_WITHDRAWAL_LIST_REQUEST',
  GET_WITHDRAWAL_LIST: 'GET_WITHDRAWAL_LIST',

  BANK_WITHDRAW_REQUEST: 'BANK_WITHDRAW_REQUEST',
  BANK_WITHDRAW: 'BANK_WITHDRAW',

  getBankList: (payload = {}) => {
    return {
      type: WITHDRAWAL_ACTIONS.GET_BANK_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: ConfigUrl.getBankList,
        query: payload
      }
    }
  },
  getWithdrawalList: (payload = {}) => {
    if (!payload) {
      payload = {
        page_size: 5,
        status: 'SUCCESS,INITIATED,PENDING'
      }
    }
    if (!payload.status) {
      payload = {
        ...payload,
        status: 'SUCCESS,INITIATED,PENDING'
      }
    }
    return {
      type: WITHDRAWAL_ACTIONS.GET_WITHDRAWAL_LIST_REQUEST,
      payload: {
        method: 'GET',
        url: ConfigUrl.withdrawalList,
        query: payload
      }
    }
  },
  requestBankWithdraw: (payload) => {
    return {
      type: WITHDRAWAL_ACTIONS.BANK_WITHDRAW_REQUEST,
      payload: {
        body: payload,
        method: 'POST',
        url: ConfigUrl.requestBankWithdraw
      }
    }
  }
}
