import { createContext, useContext, useReducer } from 'react'
import reducer from '../state/reducer.js'

// this is the context used by the all pages
export const WithdrawalContext = createContext()
// provider provide the update context value
export const WithdrawalContextProvider = (props) => {
  return (
    <WithdrawalContext.Provider value={useReducer(reducer, {})}>
      {props.children}
    </WithdrawalContext.Provider>
  )
}
// use to read the value from the global state
export const useWithdrawalContextValue = () => useContext(WithdrawalContext)
