import { useState, useEffect } from 'react'
import { get } from 'lodash/object'
import { WithdrawalWrapper } from './index.style'
import { Container, CustomText, ContentBox } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { ImageUrl } from '../../../../images'
import { formatMoney, isCreditAmount } from '../../../../helpers/utility'
import { useGetWithdrawalList } from '../state/hooks/useWithdraw'
import WarningNotifications from '../component/WarningNotifications'
import { useHistory } from 'react-router-dom'
import { useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'

function WithdrawalContainer () {
  const [showWarning, setshowWarning] = useState(true)
  const [withdrawalList, getWithdrawalListRequest] = useGetWithdrawalList()
  const [{ GET_WITHDRAWAL_LIST_LOADER }, dispatchLoader] = useLoaderContextValue()
  const history = useHistory()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_WITHDRAWAL_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_WITHDRAWAL_LIST_LOADER === undefined) {
      getWithdrawalListRequest({ page_size: 3 })
    }
  }, [getWithdrawalListRequest, GET_WITHDRAWAL_LIST_LOADER])

  const handleToCloseWarning = () => {
    setshowWarning(false)
  }

  return (
    <Container title='Tarik Saldo' loader={GET_WITHDRAWAL_LIST_LOADER}>
      <WithdrawalWrapper>
        {
          (showWarning) &&
        (
          <WarningNotifications
            onClose={handleToCloseWarning}
          />
        )
        }
        <div className='withdrawal-option'>
          <CustomText color={AgentColorPallette.black} size='16px' weight='700'>
            {'Pilih Metode Tarik Saldo'}
          </CustomText>
          <div className='transfer-option-container' onClick={() => history.push('/balance/withdrawal/form')}>
            <div className='row-item'>
              <img alt='transfer-logo' src={ImageUrl.bankTransferLogo} />
              <div>
                <CustomText color={AgentColorPallette.fontSemiGrey}>
                  {'Bank'}
                </CustomText>
                <CustomText color={AgentColorPallette.fontDarkerGrey} weight='700' size='14px'>
                  {'Transfer ke Bank'}
                </CustomText>
              </div>
            </div>
            <img src={ImageUrl.arrowRight} alt='arrow-icon' className='arrow-right' />
          </div>
        </div>
        <div className='list-container'>
          <div className='row-space-between'>
            <CustomText color={AgentColorPallette.black} weight={700} size='16px' bottom='16px'>
              {`${withdrawalList?.getWithdrawalListData?.meta_data ? withdrawalList?.getWithdrawalListData?.meta_data.total_records > 3 ? 3 : withdrawalList?.getWithdrawalListData?.meta_data.total_records : 0} Penarikan Terakhir`}
            </CustomText>
            {
              get(withdrawalList, 'meta_data.total_records', 0) > 3 && (
                <img src={ImageUrl.list} alt='list-icon' width='44px' onClick={() => history.push('/balance/withdrawal/history')} />
              )
            }
          </div>
          {
            withdrawalList?.getWithdrawalListData?.data && withdrawalList?.getWithdrawalListData?.data.map((transaction, index) =>
              <ContentBox
                heading={transaction.commission_type}
                value={isCreditAmount(transaction.amount) ? '+ ' + formatMoney(transaction.amount, 0) : formatMoney(transaction.amount, 0)}
                secondRowText={transaction.description}
                thirdRowText={transaction.transaction_date}
                color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                key={index}
              />
            )
          }
        </div>
      </WithdrawalWrapper>
    </Container>
  )
}

export default WithdrawalContainer
