import { Component } from 'react'
import PropTypes from 'prop-types'
import { WarningNotificationStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../lang/index'

class WarningNotifications extends Component {
  static propTypes = {
    onClose: PropTypes.func
  }

  handleClose = (e) => {
    e.stopPropagation()
    e.preventDefault()
    this.props.onClose()
  }

  render () {
    return (
      <WarningNotificationStyle className={this.props.className}>
        <div className='warning-text'>
          {LANG_STRINGS.withdrawalWarning}
        </div>
        <div className='warning-close' onClick={this.handleClose}>
          <i className='fas fa-times' />
        </div>
      </WarningNotificationStyle>
    )
  }
}

export default WarningNotifications
